    foreach($document['texts'] as $id=>$item){$html=$item['html']??null;if(!is_array($item)||!is_string($html)||strlen($html)>12000||strip_tags($html,'<strong><em><b><i><a><span><br>')!==$html||preg_match('~<\s*(script|style|iframe|object)|on\w+\s*=|javascript:~i',$html))content_validation_error('invalid_text');}
    foreach(['images','videos'] as $group)foreach($document[$group] as $id=>$item){$keys=['src','alt','objectFit','objectPosition','positionX','positionY','zoom','poster','autoplay','muted','loop','controls','aspectRatio'];if($group==='videos')$keys=array_merge($keys,['playsinline','mediaAssetId','mediaVersionId','posterId','posterTimestamp']);if(!is_array($item)||array_diff(array_keys($item),$keys))content_validation_error('invalid_media');foreach($item as $key=>$value){if(!is_string($key)||(!is_string($value)&&!is_bool($value)&&!is_int($value)&&!is_float($value))||(is_string($value)&&strlen($value)>4000)||(is_string($value)&&preg_match('~javascript:~i',$value)))content_validation_error('invalid_media');}}
