    foreach($document['forms'] as $id=>$form){if(!is_array($form)||!is_array($form['fields']??null)||!is_string($form['submitLabel']??null)||strlen($form['submitLabel'])>500)content_validation_error('invalid_form');$ids=[];foreach($form['fields'] as $field){if(!is_array($field)||!preg_match('/^[a-z][a-z0-9_]{0,63}$/',$field['id']??'')||isset($ids[$field['id']])||!in_array($field['type']??'', ['text','email','textarea','select','radio','checkbox'],true)||!is_string($field['label']??null)||strlen($field['label'])>500||!is_bool($field['required']??null))content_validation_error('invalid_form');$ids[$field['id']]=true;if(isset($field['options'])){if(!is_array($field['options'])||!in_array($field['type'],['select','radio'],true))content_validation_error('invalid_form');foreach($field['options'] as $option)if(!is_array($option)||!is_string($option['label']??null)||!is_string($option['value']??null)||strlen($option['label'])>500||strlen($option['value'])>200)content_validation_error('invalid_form');}}}
    $json=json_encode($document,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(strlen($json)>500000)content_validation_error('document_too_large');return $document;
